import { useCallback } from 'react';
import { logger } from '../lib/logger';
import { useUploadStore, createUploadId } from '../stores/upload.store';
import { useQuotaStore } from '../stores/quota.store';
import { useFolderStore } from '../stores/folder.store';
import { useVaultStore } from '../stores/vault.store';
import { useAuthStore } from '../stores/auth.store';
import { getSdkClient, hasSdkClient, ensureFolderRegistered } from '../lib/sdk-provider';
import { getRootFolderState } from './folder-helpers';
import type { PendingReplacement } from '../stores/upload.store';

export const MAX_FILE_SIZE = 100 * 1024 * 1024; // 100MB per FILE-01

/**
 * Check whether a drag event carries external files from the OS (Finder/Explorer)
 * rather than an internal app drag (which sets application/json).
 */
export function isExternalFileDrag(dataTransfer: DataTransfer): boolean {
  return dataTransfer.types.includes('Files') && !dataTransfer.types.includes('application/json');
}

/**
 * Hook for handling external file drops (from Finder/Explorer) anywhere in the app.
 *
 * Uses the SDK's uploadFile() for atomic encrypt -> upload -> register flow.
 * All IPNS state is managed by the SDK -- no dual-path conflicts.
 */
export function useDropUpload() {
  const isUploading = useUploadStore((s) => {
    for (const f of s.files.values()) {
      if (f.status === 'encrypting' || f.status === 'uploading') return true;
    }
    return false;
  });

  const handleFileDrop = useCallback(async (files: File[], folderId: string): Promise<boolean> => {
    // Filter out oversized files
    const oversized = files.filter((f) => f.size > MAX_FILE_SIZE);
    if (oversized.length > 0) {
      logger.error(`[Upload] Files exceed 100MB limit: ${oversized.map((f) => f.name).join(', ')}`);
      return false;
    }

    if (files.length === 0) return false;

    // Check quota
    const totalSize = files.reduce((sum, f) => sum + f.size, 0);
    const quotaStore = useQuotaStore.getState();
    if (!quotaStore.canUpload(totalSize)) {
      logger.error('[Upload] Not enough storage space for these files');
      return false;
    }

    // Check for duplicates within batch
    const batchNames = new Set<string>();
    for (const f of files) {
      if (batchNames.has(f.name)) {
        logger.error(`[Upload] Duplicate file name in selection: ${f.name}`);
        return false;
      }
      batchNames.add(f.name);
    }

    // Identify which files already exist in the target folder
    const folder = useFolderStore.getState().folders[folderId];
    const existingByName = new Map<string, string>(); // name -> fileId
    const existingFolderNames = new Set<string>();
    if (folder) {
      for (const child of folder.children) {
        if (child.type === 'file') {
          existingByName.set(child.name, child.id);
        } else if (child.type === 'folder') {
          existingFolderNames.add(child.name);
        }
      }
    }

    // Fail fast on file-folder name collisions
    const folderNameConflicts = files.filter((f) => existingFolderNames.has(f.name));
    if (folderNameConflicts.length > 0) {
      logger.error(
        `[Upload] Cannot upload file(s) with the same name as an existing folder: ${folderNameConflicts.map((f) => f.name).join(', ')}`
      );
      return false;
    }

    const newFiles = files.filter((f) => !existingByName.has(f.name));
    const duplicateFiles = files.filter((f) => existingByName.has(f.name));

    if (!hasSdkClient()) {
      logger.error('[Upload] SDK not initialized -- please log in again');
      return false;
    }

    const client = getSdkClient();

    // Resolve parent folder and ensure it's registered in the SDK
    const folders = useFolderStore.getState().folders;
    const vault = useVaultStore.getState();
    const parentFolder =
      folderId === 'root' ? getRootFolderState(vault, folders) : folders[folderId];
    if (!parentFolder) {
      logger.error('[Upload] Parent folder not found');
      return false;
    }
    ensureFolderRegistered(parentFolder);

    const uploadedCids: string[] = []; // Track for cleanup on failure
    let currentUploadId: string | undefined;

    try {
      // Upload new files via SDK (atomic: encrypt -> IPFS -> FilePointer -> IPNS publish)
      for (const file of newFiles) {
        const uploadId = createUploadId(file.name);
        currentUploadId = uploadId;
        useUploadStore.getState().addFile(uploadId, file.name, folderId, file);

        if (useUploadStore.getState().files.get(uploadId)?.status === 'cancelled') {
          throw new Error('Upload cancelled by user');
        }

        const data = new Uint8Array(await file.arrayBuffer());

        const result = await client.uploadFile(
          parentFolder.ipnsName,
          data,
          file.name,
          file.type || 'application/octet-stream',
          (percent) => useUploadStore.getState().updateFileProgress(uploadId, percent)
        );

        uploadedCids.push(result.cid);
        useUploadStore.getState().setFileStatus(uploadId, 'complete');
      }

      // Handle duplicate files: encrypt + upload to IPFS, then surface as pending replacements
      // (These don't get registered in the folder -- the user decides via the Replace dialog)
      // Duplicate files always upload to CipherBox relay (not BYO node) because
      // they're staged for the replacement dialog. Once the user confirms, the
      // replacement flow uses SDK's uploadFile() which respects pinning mode.
      if (duplicateFiles.length > 0) {
        const replacements: PendingReplacement[] = [];

        // Hoist dynamic imports before the loop to avoid per-iteration async overhead
        const { encryptFile } = await import('../services/file-crypto.service');
        const { addToIpfs } = await import('../lib/api/ipfs');

        for (const file of duplicateFiles) {
          const uploadId = createUploadId(file.name);
          currentUploadId = uploadId;
          useUploadStore.getState().addFile(uploadId, file.name, folderId, file);

          if (useUploadStore.getState().files.get(uploadId)?.status === 'cancelled') {
            throw new Error('Upload cancelled by user');
          }

          // For duplicates, we only encrypt + upload to IPFS (don't register in folder)
          // Use the old upload service for this since SDK's uploadFile registers in folder
          const userPublicKey = useAuthStore.getState().vaultKeypair?.publicKey;
          if (!userPublicKey) throw new Error('No keypair available');
          const encrypted = await encryptFile(file, userPublicKey);
          // Pass a clean Uint8Array copy -- never use .buffer (may include extra bytes)
          const blob = new Blob([new Uint8Array(encrypted.ciphertext)], {
            type: 'application/octet-stream',
          });

          const cancelToken = useUploadStore.getState().files.get(uploadId)?.cancelSource?.token;
          const ipfsResult = await addToIpfs(
            blob,
            (percent) => useUploadStore.getState().updateFileProgress(uploadId, percent),
            cancelToken
          );

          uploadedCids.push(ipfsResult.cid);
          useUploadStore.getState().setFileStatus(uploadId, 'complete');

          const existingFileId = existingByName.get(file.name);
          if (existingFileId) {
            replacements.push({
              fileName: file.name,
              fileId: existingFileId,
              parentId: folderId,
              encryptedData: {
                cid: ipfsResult.cid,
                wrappedKey: encrypted.wrappedKey,
                iv: encrypted.iv,
                size: file.size,
                encryptionMode: encrypted.encryptionMode,
              },
            });
          }
        }

        if (replacements.length > 0) {
          useUploadStore.getState().setPendingReplacements(replacements);
        }
      }

      return true;
    } catch (err) {
      const message = (err as Error).message;
      if (message !== 'Upload cancelled by user' && currentUploadId) {
        useUploadStore.getState().setFileStatus(currentUploadId, 'error', message);
      }
      // Best-effort cleanup: unpin orphaned CIDs from failed upload
      if (uploadedCids.length > 0) {
        import('../lib/api/ipfs')
          .then(({ unpinFromIpfs }) => {
            for (const cid of uploadedCids) {
              unpinFromIpfs(cid).catch((err) =>
                logger.warn('[Upload] Unpin orphaned CID failed:', err)
              );
            }
          })
          .catch((err) => logger.warn('[Upload] Failed to load IPFS module for cleanup:', err));
      }
      return false;
    } finally {
      // Refresh quota from server
      await useQuotaStore.getState().fetchQuota();
    }
  }, []);

  return { handleFileDrop, isUploading };
}

import { type DragEvent, type MouseEvent } from 'react';
import type { FolderChild } from '@cipherbox/core';
import { useUploadStore } from '../../stores/upload.store';
import type { PerFileUpload } from '../../stores/upload.store';
import { FileListItem, type DragItem } from './FileListItem';
import { UploadListItem } from './UploadListItem';
import { ParentDirRow } from './ParentDirRow';

/**
 * Virtual entry representing an in-progress upload in the sorted file list.
 * The `_uploading` flag discriminates it from real FolderChild items.
 */
type UploadVirtualEntry = {
  type: 'file';
  id: string;
  name: string;
  fileMetaIpnsName: '';
  createdAt: number;
  modifiedAt: number;
  _uploading: true;
};

type FileListProps = {
  /** Items to display (files and folders) */
  items: FolderChild[];
  /** Set of currently selected item IDs */
  selectedIds: Set<string>;
  /** Parent folder ID (for drag operations) */
  parentId: string;
  /** Parent folder's decrypted AES-256 key (for resolving file sizes) */
  folderKey: Uint8Array | null;
  /** Whether to show [..] PARENT_DIR row (non-root folders) */
  showParentRow?: boolean;
  /** Callback when [..] row is clicked to navigate up */
  onNavigateUp?: () => void;
  /** Callback when an item is selected (with modifier key info) */
  onSelect: (
    itemId: string,
    event: { ctrlKey: boolean; shiftKey: boolean; metaKey: boolean }
  ) => void;
  /** Callback to select/deselect all items */
  onSelectAll: () => void;
  /** Callback when navigating into a folder */
  onNavigate: (folderId: string) => void;
  /** Callback when context menu is requested */
  onContextMenu: (event: MouseEvent, item: FolderChild) => void;
  /** Callback when drag starts */
  onDragStart: (event: DragEvent, item: FolderChild) => void;
  /** Callback when items are dropped onto a folder */
  onDropOnFolder?: (items: DragItem[], sourceParentId: string, destFolderId: string) => void;
  /** Callback when external files are dropped onto a folder */
  onExternalFileDrop?: (files: File[], destFolderId: string) => void;
  /** Callback to re-trigger upload for a failed file (retry button in UploadListItem) */
  onRetryUpload?: (file: File) => void;
};

/**
 * Sort items: folders first, then files, both alphabetically.
 */
function sortItems(items: FolderChild[]): FolderChild[] {
  return [...items].sort((a, b) => {
    // Folders come first
    if (a.type === 'folder' && b.type !== 'folder') return -1;
    if (a.type !== 'folder' && b.type === 'folder') return 1;

    // Within same type, sort alphabetically (case-insensitive)
    return a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
  });
}

/**
 * File list component displaying files and folders in a columnar layout.
 *
 * Renders items sorted by type (folders first) then alphabetically.
 * Supports selection, navigation, context menu, and drag operations.
 *
 * @example
 * ```tsx
 * function FileBrowser() {
 *   const { currentFolder } = useFolderNavigation();
 *   const [selectedId, setSelectedId] = useState<string | null>(null);
 *
 *   return (
 *     <FileList
 *       items={currentFolder?.children ?? []}
 *       selectedId={selectedId}
 *       parentId={currentFolder?.id ?? 'root'}
 *       onSelect={setSelectedId}
 *       onNavigate={navigateTo}
 *       onContextMenu={handleContextMenu}
 *       onDragStart={handleDragStart}
 *     />
 *   );
 * }
 * ```
 */
export function FileList({
  items,
  selectedIds,
  parentId,
  folderKey,
  showParentRow,
  onNavigateUp,
  onSelect,
  onSelectAll,
  onNavigate,
  onContextMenu,
  onDragStart,
  onDropOnFolder,
  onExternalFileDrop,
  onRetryUpload,
}: FileListProps) {
  // Subscribe to upload entries for this folder only (IDs + filenames + status, not progress).
  // Progress updates re-render individual UploadListItem rows via their own fine-grained selectors.
  const uploadEntries = useUploadStore(
    (s) => {
      const entries: { id: string; filename: string; status: PerFileUpload['status'] }[] = [];
      for (const f of s.files.values()) {
        if (f.targetFolderId === parentId && f.status !== 'cancelled') {
          entries.push({ id: f.id, filename: f.filename, status: f.status });
        }
      }
      return entries;
    },
    (a, b) => {
      if (a.length !== b.length) return false;
      for (let i = 0; i < a.length; i++) {
        if (a[i].id !== b[i].id || a[i].status !== b[i].status) return false;
      }
      return true;
    }
  );

  // Create virtual entries for sorting alongside real items
  const uploadVirtualEntries: UploadVirtualEntry[] = uploadEntries.map((f) => ({
    type: 'file' as const,
    id: f.id,
    name: f.filename,
    fileMetaIpnsName: '' as const,
    createdAt: 0,
    modifiedAt: 0,
    _uploading: true as const,
  }));

  // Filter out real files that match completing uploads to prevent duplicates (Pitfall 5)
  const completingNames = new Set(
    uploadEntries.filter((e) => e.status === 'complete').map((e) => e.filename)
  );
  const filteredItems = items.filter(
    (item) => !(item.type === 'file' && completingNames.has(item.name))
  );

  // Merge and sort all items together
  const allItems = [...filteredItems, ...uploadVirtualEntries];
  const sortedItems = sortItems(allItems as FolderChild[]);

  // Select-all uses real item count only (upload rows are not selectable)
  const allSelected = items.length > 0 && selectedIds.size === items.length;

  return (
    <div className="file-list" role="grid">
      {/* Header row */}
      <div className="file-list-header" role="row">
        <div className="file-list-header-name" role="columnheader">
          <span
            className="file-list-header-checkbox"
            onClick={onSelectAll}
            role="checkbox"
            aria-checked={allSelected}
            aria-label={allSelected ? 'Deselect all' : 'Select all'}
            tabIndex={0}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                onSelectAll();
              }
            }}
          >
            {allSelected ? '[x]' : '[ ]'}
          </span>
          [NAME]
        </div>
        <div className="file-list-header-size" role="columnheader">
          [SIZE]
        </div>
        <div className="file-list-header-date" role="columnheader">
          [MODIFIED]
        </div>
        {/* Empty header cell for mobile action column - hidden on desktop via CSS */}
        <div className="file-list-header-actions" aria-hidden="true" />
      </div>

      {/* Item rows */}
      <div className="file-list-body" role="rowgroup">
        {showParentRow && onNavigateUp && <ParentDirRow onActivate={onNavigateUp} />}
        {sortedItems.map((item) =>
          '_uploading' in item ? (
            <UploadListItem key={item.id} fileId={item.id} onRetry={onRetryUpload} />
          ) : (
            <FileListItem
              key={item.id}
              item={item}
              isSelected={selectedIds.has(item.id)}
              parentId={parentId}
              selectedIds={selectedIds}
              allItems={items}
              folderKey={folderKey}
              onSelect={onSelect}
              onNavigate={onNavigate}
              onContextMenu={onContextMenu}
              onDragStart={onDragStart}
              onDrop={
                onDropOnFolder && item.type === 'folder'
                  ? (dragItems, sourceParentId) =>
                      onDropOnFolder(dragItems, sourceParentId, item.id)
                  : undefined
              }
              onExternalFileDrop={item.type === 'folder' ? onExternalFileDrop : undefined}
            />
          )
        )}
      </div>
    </div>
  );
}

